class State {
 public static string Text = "A";
 public static int N = 1;
 public static long L = 9223372036854775807L;
 public static int Property { get; set; } = 3;
 static State() { Text += "B"; }
}
int Right() { State.N = 20; return 4; }
void Main() {
 Print(State.Text += 2); Print(State.N += Right()); Print(State.N);
 Print(State.L++); Print(State.L); Print(--State.Property);
 var n = 2; Print(State.Property += ++n); Print(n);
}
